// Values come from .env via env.js (generated by `node scripts/build-env.mjs`).
// The project URL and publishable key are public by design (Row Level Security protects the data).
// NEVER put a service-role key or database password in .env.
import ENV from "./env.js";

const list = (value) => (value || "").split(",").map((item) => item.trim()).filter(Boolean);

export const CONFIG = {
  supabaseUrl: ENV.SUPABASE_URL || "",
  supabasePublishableKey: ENV.SUPABASE_PUBLISHABLE_KEY || "",

  teams: list(ENV.TEAM_OPTIONS).length ? list(ENV.TEAM_OPTIONS) : ["AF", "CYD", "PB"],
  nameMaxLength: 40,

  // The database enforces these two. Keep them equal to
  // public.wot_room_capacity() and public.wot_complaint_threshold() in supabase/schema.sql.
  roomCapacity: 30,
  complaintThreshold: 2
};

export function isConfigured() {
  return /^https?:\/\//.test(CONFIG.supabaseUrl.trim()) && CONFIG.supabasePublishableKey.trim().length > 0;
}
